"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  19 Oktober 2024                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  19 Oktober 2024                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during October 2015\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 19 Oktober 2024\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Meshing a pipe with layers (45 degree)${NC}\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"` \n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: October 2015                    #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -f constant/triSurface/*.eMesh paraview.foam\nrm -rf 0 log* constant/extend*\n\n\n#-------------------------------------------------------------------------------\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  19 Oktober 2024                    #\n#-------------------------------------------------#\n# Topic:       Meshing a pipe (45 degree)         #\n# OpenFOAM:    version 12 (Foundation)             #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create feature edges"\nsurfaceFeatures >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Scale background mesh"\ntransformPoints "scale=(1000 1000 1000)" >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh"\nsnappyHexMesh >> logMeshing\n\n\n#------------------------------------------------------------------------------\n#echo -e "   - Scale the meshed geometry back"\n#transformPoints -scale "(1e-3 1e-3 1e-3)" >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Note 98.6% layers are generated. Changing the layer settings can"\necho -e "     result in a 100% of layer generation. Problem here is the outlet"\necho -e "     that causes tiny problems due to the fact that the mesh is "\necho -e "     built under 45°. A 90° pipe will have 100% without changing the"\necho -e "     layerControl parameters."\n\ntouch paraview.foam\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\\n\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     simpleFoam;\n\nstartFrom       latestTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         500;\n\ndeltaT          1;\n\nwriteControl    timeStep;\n\nwriteInterval   100;\n\npurgeWrite      0;\n\nwriteFormat     binary;\n\nwritePrecision  6;\n\nwriteCompression uncompressed;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable true;\n\n\n// ************************************************************************* //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         steadyState;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(U)         cellLimited Gauss linear 1;\n}\n\ndivSchemes\n{\n    default         none;\n    div(phi,U)      bounded Gauss linearUpwindV grad(U);\n    div(phi,k)      bounded Gauss upwind;\n    div(phi,omega)  bounded Gauss upwind;\n    div((nuEff*dev(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear corrected;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\nfluxRequired\n{\n    default         no;\n    p;\n}\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    p\n    {\n        solver           GAMG;\n        tolerance        1e-7;\n        relTol           0.01;\n        smoother         GaussSeidel;\n        nPreSweeps       0;\n        nPostSweeps      2;\n        cacheAgglomeration on;\n        agglomerator     faceAreaPair;\n        nCellsInCoarsestLevel 10;\n        mergeLevels      1;\n    }\n\n    U\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n\n    k\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n\n    omega\n    {\n        solver           smoothSolver;\n        smoother         GaussSeidel;\n        tolerance        1e-8;\n        relTol           0.1;\n        nSweeps          1;\n    }\n}\n\nSIMPLE\n{\n    nNonOrthogonalCorrectors 0;\n}\n\npotentialFlow\n{\n    nNonOrthogonalCorrectors 10;\n}\n\nrelaxationFactors\n{\n    fields\n    {\n        p               0.3;\n    }\n    equations\n    {\n        U               0.7;\n        k               0.7;\n        omega           0.7;\n    }\n}\n\ncache\n{\n    grad(U);\n}\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\nminFaceWeight 0.02;\n\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh true;\nsnap            true;\naddLayers       true;\n\n\n// Geometry. Definition of all surfaces. All surfaces are of class\n// searchableSurface.\n// Surfaces are used\n// - to specify refinement for any mesh cell intersecting it\n// - to specify refinement for any mesh cell inside/outside/near\n// - to \'snap\' the mesh boundary to the surface\ngeometry\n{\n    regionSTL\n    {\n        file "regionSTL.stl";\n        type triSurfaceMesh;\n        regions\n        {\n\n            inlet   { name inlet; }\n            outlet  { name outlet; }\n            wall    { name wall; }\n        }\n    }\n};\n\n\n\n// Settings for the castellatedMesh generation.\ncastellatedMeshControls\n{\n    // Refinement parameters\n    // ~~~~~~~~~~~~~~~~~~~~~\n\n    // If local number of cells is >= maxLocalCells on any processor\n    // switches from from refinement followed by balancing\n    // (current method) to (weighted) balancing before refinement.\n    maxLocalCells 100000;\n\n    // Overall cell limit (approximately). Refinement will stop immediately\n    // upon reaching this number so a refinement level might not complete.\n    // Note that this is the number of cells before removing the part which\n    // is not \'visible\' from the keepPoint. The final number of cells might\n    // actually be a lot less.\n    maxGlobalCells 7000000;\n\n    // The surface refinement loop might spend lots of iterations refining just a\n    // few cells. This setting will cause refinement to stop if <= minimumRefine\n    // are selected for refinement. Note: it will at least do one iteration\n    // (unless the number of cells to refine is 0)\n    minRefinementCells 0;\n\n    // Allow a certain level of imbalance during refining\n    // (since balancing is quite expensive)\n    // Expressed as fraction of perfect balance (= overall number of cells /\n    // nProcs). 0=balance always.\n    maxLoadUnbalance 0.10;\n\n\n    // Number of buffer layers between different levels.\n    // 1 means normal 2:1 refinement restriction, larger means slower\n    // refinement.\n    nCellsBetweenLevels 5;\n\n\n\n    // Explicit feature edge refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies a level for any cell intersected by its edges.\n    // This is a featureEdgeMesh, read from constant/geometry for now.\n    features\n    (\n        {\n            file "regionSTL.eMesh";\n            levels ((10 3));\n        }\n    );\n\n\n\n    // Surface based refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies two levels for every surface. The first is the minimum level,\n    // every cell intersecting a surface gets refined up to the minimum level.\n    // The second level is the maximum level. Cells that \'see\' multiple\n    // intersections where the intersections make an\n    // angle > resolveFeatureAngle get refined up to the maximum level.\n\n    refinementSurfaces\n    {\n        regionSTL\n        {\n            // Surface-wise min and max refinement level\n            level (0 0);\n            regions\n            {\n                inlet   { level (0 0); }\n                outlet  { level (0 0); }\n                wall    { level (2 2); }\n            }\n        }\n    }\n\n    // Resolve sharp angles\n    resolveFeatureAngle 60;\n\n\n    // Region-wise refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies refinement level for cells in relation to a surface. One of\n    // three modes\n    // - distance. \'levels\' specifies per distance to the surface the\n    //   wanted refinement level. The distances need to be specified in\n    //   descending order.\n    // - inside. \'levels\' is only one entry and only the level is used. All\n    //   cells inside the surface get refined up to the level. The surface\n    //   needs to be closed for this to be possible.\n    // - outside. Same but cells outside.\n\n    refinementRegions\n    {\n    }\n\n\n    // Mesh selection\n    // ~~~~~~~~~~~~~~\n\n    // After refinement patches get added for all refinementSurfaces and\n    // all cells intersecting the surfaces get put into these patches. The\n    // section reachable from the insidePoint is kept.\n    // NOTE: This point should never be on a face, always inside a cell, even\n    // after refinement.\n    insidePoint (0 0 10);\n\n\n    // Whether any faceZones (as specified in the refinementSurfaces)\n    // are only on the boundary of corresponding cellZones or also allow\n    // free-standing zone faces. Not used if there are no faceZones.\n    allowFreeStandingZoneFaces false;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 3;\n\n    //- Relative distance for points to be attracted by surface feature point\n    //  or edge. True distance is this factor times local\n    //  maximum edge length.\n    tolerance 2.0;\n\n    //- Number of mesh displacement relaxation iterations.\n    nSolveIter 30;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n\n    nFeatureSnapIter    5;\n    implicitFeatureSnap false;\n    explicitFeatureSnap true;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    // Are the thickness parameters below relative to the undistorted\n    // size of the refined cell outside layer (true) or absolute sizes (false).\n    relativeSizes false;\n\n    // Per final patch (so not geometry!) the layer information\n    layers\n    {\n        wall\n        {\n            nSurfaceLayers 3;\n        }\n    }\n\n    // Expansion factor for layer mesh\n    expansionRatio 1.2;\n\n    // Wanted thickness of final added cell layer. If multiple layers\n    // is the thickness of the layer furthest away from the wall.\n    // Relative to undistorted size of cell outside layer.\n    // See relativeSizes parameter.\n    finalLayerThickness 1.0;\n\n    // Minimum thickness of cell layer. If for any reason layer\n    // cannot be above minThickness do not add layer.\n    // Relative to undistorted size of cell outside layer.\n    minThickness 0.01;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    nGrow 0;\n\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 100;\n\n    // At non-patched sides allow mesh to slip if extrusion direction makes\n    // angle larger than slipFeatureAngle. Default is 0.5*featureAngle.\n    slipFeatureAngle 30;\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 3;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 1;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 2;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.3;\n\n    // Angle used to pick up medial axis points\n    minMedianAxisAngle 90;\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n    // Overall max number of layer addition iterations\n    nLayerIter 50;\n}\n\n\n\n// Generic mesh quality settings. At any undoable phase these determine\n// where to undo.\nmeshQualityControls\n{\n    //- Maximum non-orthogonality allowed. Set to 180 to disable.\n    maxNonOrtho 65;\n\n    //- Max skewness allowed. Set to <0 to disable.\n    maxBoundarySkewness 20;\n    maxInternalSkewness 4;\n\n    //- Max concaveness allowed. Is angle (in degrees) below which concavity\n    //  is allowed. 0 is straight face, <0 would be convex face.\n    //  Set to 180 to disable.\n    maxConcave 80;\n\n    //- Minimum projected area v.s. actual area. Set to -1 to disable.\n    minFlatness 0.5;\n\n    //- Minimum cell pyramid volume relative to min bounding box length^3\n    //  Set to a fraction of the smallest cell volume expected.\n    //  Set to very negative number (e.g. -1e30) to disable.\n    minVol -1e30;\n\n    minTetQuality 1e-30;\n\n    //- Minimum face twist. Set to <-1 to disable. dot product of face normal\n    //  and face centre triangles normal\n    minTwist 0.02;\n\n    //- Minimum normalised cell determinant\n    //  1 = hex, <= 0 = folded or flattened illegal cell\n    minDeterminant 0.001;\n\n    //- minFaceWeight (0 -> 0.5)\n    minFaceWeight 0.02;\n\n    //- minVolRatio (0 -> 1)\n    minVolRatio 0.01;\n\n    // Advanced\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- Amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\n// Merge tolerance. Is fraction of overall bounding box of initial mesh.\n// Note: the write tolerance needs to be higher than this.\nmergeTolerance 1e-6;\n\n\n// ************************************************************************* //\n',
    'system/surfaceFeaturesDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      surfaceFeatureExtractDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nregionSTL\n{\n    // The files of which you want to extract the features\n    // Located in constant/triSurface\n    surfaces\n    (\n        "regionSTL.stl"\n    );\n\n    //- Since 6.x\n    //  Needed especially for bad triangulations.\n    //  Always check your feature edge mesh\n    trimFeatures\n    {\n        //- Feature edges that contains less than \'minElem\' of edges are\n        //  removed automatically\n        minElem 5;\n\n        //- Remove feature edges that are less than the total length of [m]\n        minLen  0.001;\n    }\n\n    //- This is the angle between faces\n    includedAngle       150;\n\n    //- Since 6.x\n    //  Outputs the curvature of the surface\n    //curvature           no;\n\n    //- Since 6.x\n    //  Outputs the priximity of points and edges to each other\n    //featureProximity    no;\n\n    //- Since 6.x\n    //  The maximum search distance to use, when looking for other feature\n    //  points and edges\n    //maxFeatureProximity  1;\n\n    //- Write features for post processing into *.obj format\n    //  *.obj can be read by ParaView\n    writeObj            yes;\n\n    //- Write the surface proximity and curvature to the VTK format\n    writeVTK            no;\n}\n\n\n// ************************************************************************* //\n',
}
